brahe.defense.inspect.excerpt:
async def inspect(self, messages, stage="model_input"):
    if self.mode == "off":
        return
    run = security_run.get()
    try:
        if not self.valid or not self.key:
            raise ValueError("Invalid security configuration")
        async with httpx.AsyncClient(timeout=self.timeout, follow_redirects=False) as client:
            response = await client.post(self.endpoint,
                headers={"X-Cisco-AI-Defense-API-Key": self.key},
                json={"messages": messages, "metadata": {"src_app": "fsi-ai-studio-brahe-bank",
                      "client_transaction_id": f"{run.request_id if run else uuid.uuid4()}:{stage}"}})
            response.raise_for_status()
            verdict = response.json()
        if type(verdict.get("is_safe")) is not bool:
            raise ValueError("Missing inspection verdict")
    except Exception:
        if run:
            run.errors += 1
        if not self.fail_open:
            raise DefenseUnavailable("AI Defense inspection is unavailable. No answer was released.") from None
        return
    if run:
        run.checks += 1
        event_id = verdict.get("event_id")
        if isinstance(event_id, str) and event_id and event_id not in run.event_ids:
            run.event_ids.append(event_id)
        if not verdict["is_safe"]:
            run.blocked += 1
    # Attach only verdict metadata to the current model span, never payloads.
    from opentelemetry import trace
    span = trace.get_current_span()
    span.set_attribute("cisco.ai_defense.last_stage", stage)
    span.set_attribute("cisco.ai_defense.is_safe", verdict["is_safe"])
    if verdict.get("event_id"):
        span.set_attribute("cisco.ai_defense.event_id", verdict["event_id"])
    if not verdict["is_safe"] and self.mode == "enforce":
        raise DefenseBlocked("AI Defense blocked this interaction. No answer was released.")

brahe.controls.check.excerpt:
async def check(self, stage, request, run, *, answer=None, evidence=None, history=None, logger=None):
    try:
        if not self.ready:
            raise ControlsUnavailable("Banking controls are unavailable.")
        if stage == "pre":
            verdict = await self.judge(ScopeVerdict, SCOPE_POLICY, {"request": request, "history": history or []}, logger)
            await asyncio.wait_for(self.enforce(SCOPE_STEP, "pre", verdict, run, logger), 20)
        else:
            verdict = await self.judge(AnswerVerdict, ANSWER_POLICY,
                {"request": request, "answer": answer, "tool_evidence": evidence or []}, logger)
            await asyncio.wait_for(self.enforce(ANSWER_STEP, "post", verdict, run, logger), 20)
    except (DefenseBlocked, DefenseUnavailable, ControlsBlocked):
        raise
    except Exception:
        run.status = "unavailable"
        raise ControlsUnavailable("Agent Observability quality checks are unavailable. No answer was released.") from None

brahe.controls.enforce.excerpt:
async def enforce(self, step, stage, verdict, run, logger=None):
    self.verify_controls()
    ids = {}
    if logger is not None:
        parent = logger.current_parent()
        if parent is None:
            raise ControlsUnavailable("Control trace context is unavailable.")
        root = parent
        while getattr(root, "parent", None) is not None:
            root = root.parent
        ids = {"trace_id": str(root.id), "span_id": str(parent.id)}
    result = await agent_control.evaluate_controls(step, agent_name=AGENT_NAME, stage=stage,
        **{"input" if stage == "pre" else "output": verdict}, **ids)
    seen = set()
    for blocked, items in [(True, result.matches), (False, result.non_matches)]:
        for item in items or []:
            if item.control_name not in POLICIES:
                continue
            seen.add(item.control_name)
            run.checks.append({"name": POLICIES[item.control_name][0], "status": "blocked" if blocked else "allowed",
                "control_id": item.control_id, "execution_id": str(item.control_execution_id) if item.control_execution_id else None})
    expected = {n for n, p in POLICIES.items() if p[2] == step}
    if result.errors:
        raise ControlsUnavailable("Agent Control did not complete all required checks.")
    if not result.is_safe:
        # The hosted engine may short-circuit after a denying match. That is
        # a real block, not a missing-check error. Do not fabricate later checks.
        run.status = "blocked"
        raise ControlsBlocked("Agent Observability blocked this response under the banking quality policy.")
    if not expected.issubset(seen):
        raise ControlsUnavailable("Agent Control did not complete all required checks.")
    run.status = "allowed"

brahe.trace.excerpt:
def span(self):
    provider = self.provider or trace.get_tracer_provider()
    # Do not record exception messages; upstream errors may contain prompts.
    return provider.get_tracer("fsi.banking").start_as_current_span("brahe-bank.request", record_exception=False, set_status_on_exception=False)

def delivery(self, trace_id):
    result = {"status": "not_configured", "trace_id": trace_id}
    if not self.exporter:
        return result
    flushed = self.provider.force_flush(timeout_millis=6000)
    with self.exporter.lock:
        item = dict(self.exporter.deliveries.get(trace_id, {}))
    result.update(status="delivery_failed" if item.get("failed") else "accepted_by_endpoint" if flushed and item.get("span_count") else "delivery_pending", span_count=item.get("span_count", 0))
    return result

